import{t as e}from"./jsx-runtime-CY_jTiqj.js";import{r as t}from"./ThemeToggle-vCpx62jE.js";import{C as n,E as r,M as i,N as a,O as o,P as s,T as c,_ as l,k as u,l as d,n as f,o as p,p as m,t as h}from"./shared-BLp3PbbW.js";import{t as g}from"./copy-C7OsvOjD.js";import{t as _}from"./database-B9dOoFl-.js";import{t as v}from"./CodeEditor-DqHMt3P8.js";var y=t(`Tags`,[[`path`,{d:`m15 5 6.3 6.3a2.4 2.4 0 0 1 0 3.4L17 19`,key:`1cbfv1`}],[`path`,{d:`M9.586 5.586A2 2 0 0 0 8.172 5H3a1 1 0 0 0-1 1v5.172a2 2 0 0 0 .586 1.414L8.29 18.29a2.426 2.426 0 0 0 3.42 0l3.58-3.58a2.426 2.426 0 0 0 0-3.42z`,key:`135mg7`}],[`circle`,{cx:`6.5`,cy:`9.5`,r:`.5`,fill:`currentColor`,key:`5pm5xn`}]]),b=e();function x({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{variant:`project`,chip:e??`Блок 7 · Объектная модель`,title:`Независимые tags и совместимость записи`,intro:`Добавим к подготовленной dataclass Task список меток. Разберём отдельный default для каждого объекта, проверку явно переданных значений и копии на границах словаря. Рабочий CLI пока останется на старом четырёхпольном формате.`,tags:[{icon:(0,b.jsx)(y,{size:14}),label:`изменяемое поле`},{icon:(0,b.jsx)(g,{size:14}),label:`владение данными`},{icon:(0,b.jsx)(_,{size:14}),label:`совместимая запись`}]}),(0,b.jsxs)(s,{number:`00`,title:`От четырёх полей к отдельным меткам`,children:[(0,b.jsx)(o,{children:`После подготовки модели в app.models должна быть одна dataclass Task с четырьмя проверенными полями и конвертерами. Если в вашем проекте её ещё нет, сначала завершите предыдущий шаг. Пока Planner читает старые словари, мы добавим модели tags и проследим, кто может менять этот список после создания и выдачи записи.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Есть одна dataclass Task с четырьмя проверенными полями и явными конвертерами.`},{title:`Новый вопрос`,description:`Как добавить изменяемый список и не разделить его случайно между объектами и записями?`},{title:`Результат`,description:`Подготовим независимые tags и чтение старой полной записи, не переключая рабочий JSON.`}]}),(0,b.jsx)(`p`,{children:`Здесь метка помогает отнести задачу к теме, например к Python или тестированию. Она не добавляет поиск по меткам, новую команду CLI или отдельную сущность Planner. Мы расширяем только модель и её границу со словарём; действующая программа сохранит прежний путь до согласованной миграции.`}),(0,b.jsx)(r,{tone:`warn`,children:`Перед практикой сверим, что в app.models уже есть одна dataclass Task после предыдущего шага. Если такой опоры в проекте пока нет, сначала завершим этот шаг; вторую Task или параллельный Planner не создаём.`})]}),(0,b.jsxs)(s,{number:`01`,title:`Договор для tags начинается со значения`,children:[(0,b.jsx)(o,{children:`Прежде чем добавлять поле, договоримся, какие данные оно хранит. Здесь tags будет списком строк. Каждая строка должна остаться непустой после удаления внешних пробелов, а порядок введённых меток сохраняется.`}),(0,b.jsxs)(`p`,{children:[`Такой договор оставляет решение предсказуемым. Значения `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`"python"`}),` и`,` `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`"tests"`}),` подходят. Строка с одними пробелами не описывает категорию, поэтому её нужно отклонить. Число тоже не превращается в строку само собой: иначе ошибка в вызывающем коде незаметно меняет данные.`]}),(0,b.jsx)(h,{caption:`При очистке меняются строки, но сохраняются их места и повторы`,children:(0,b.jsxs)(p,{label:`Договор меток на примере`,children:[(0,b.jsx)(d,{title:`Получили список`,children:(0,b.jsx)(`p`,{children:`[" python ", "повтор", "python"]`})}),(0,b.jsx)(f,{label:`strip для каждой строки`}),(0,b.jsx)(d,{title:`Приняли список`,children:(0,b.jsx)(`p`,{children:`["python", "повтор", "python"]`})})]})}),(0,b.jsx)(`p`,{children:`На входе ["ok", "  "] очистка превратит второй элемент в пустую строку: отклоняем весь список, даже если первый элемент корректен. Пустой список [] допустим. None и строка вместо списка запрещены. Это разные случаи: «новое поле отсутствует в старой записи» мы обработаем отдельно.`}),(0,b.jsxs)(`p`,{children:[`Мы не удаляем повторяющиеся метки и не сортируем список. В этом занятии таких правил нет. Если исходный порядок был `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`["python", "review"]`}),`, он таким и останется. Позже Planner может выбрать отдельную политику поиска или уникальности, но добавлять её сейчас означало бы менять договор без учебной и проектной причины.`]}),(0,b.jsx)(v,{code:`labels: list[str] = ["python", "review"]`}),(0,b.jsxs)(`p`,{children:[`Запись `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`list[str]`}),` сообщает, что ожидается список строк. Это аннотация, то есть описание интерфейса для читающего код и инструментов. Python не проверит каждый элемент автоматически: проверку типов и пустых после нормализации значений выполняет наш код.`]}),(0,b.jsx)(r,{children:`Сначала проверяем вход и приводим разрешённые пробелы к единому виду. Затем сохраняем результат в Task. Если проверка не прошла, объект не получает неподходящий список.`})]}),(0,b.jsxs)(s,{number:`02`,title:`default_factory создаёт отдельный контейнер`,children:[(0,b.jsx)(o,{children:`У списка есть важное свойство: его можно менять после создания. Если двум экземплярам выдать один и тот же список по умолчанию, метка, добавленная одной задаче, появится и у другой. Поле dataclass поэтому получает не готовый общий список, а способ создать новый список при каждом создании объекта.`}),(0,b.jsxs)(`p`,{children:[`Для этого используется `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`field(default_factory=list)`}),`. Функция`,` `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`list`}),` передаётся как значение, которое можно вызвать позже. Скобок у неё нет: `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`list()`}),` создало бы список сразу, а фабрика вызывает переданную функцию для каждого нового экземпляра.`]}),(0,b.jsx)(`p`,{children:`Представим два одинаковых чистых блокнота, подготовленных по одному шаблону. У каждого человека свой физический блокнот, поэтому запись в первом не появляется во втором. Шаблон соответствует фабрике, а каждый экземпляр блокнота соответствует отдельному списку поля. Аналогия заканчивается на создании контейнера: Python не понимает смысл меток, их проверяют отдельные правила.`}),(0,b.jsx)(v,{code:`from dataclasses import dataclass, field

@dataclass
class ReadingList:
    titles: list[str] = field(default_factory=list)

first = ReadingList()
second = ReadingList()
first.titles.append("Основы Python")
print(first.titles)
print(second.titles)`}),(0,b.jsx)(`p`,{children:`Здесь first и second вызывают конструктор без titles. Фабрика срабатывает дважды, поэтому first.titles is second.titles даст False. Сначала оба списка равны по содержимому (оба пусты), но после first.titles.append второй остаётся пустым. Метод append меняет список на месте: он не создаёт новый список и не обновляет соседний экземпляр. Проверьте это сравнением is, а не только печатью значений: так мы отличаем независимые контейнеры от двух имён одного списка.`}),(0,b.jsx)(l,{code:`from dataclasses import dataclass, field

@dataclass
class ReadingList:
    titles: list[str] = field(default_factory=list)

given = ["готово"]
third = ReadingList(titles=given)
given.append("позже")
print(third.titles is given)
print(third.titles)`,output:`True
['готово', 'позже']`,hint:`Здесь список передали явно. Сработает ли default_factory и откуда third возьмёт значения?`}),(0,b.jsx)(`p`,{children:`В этом опыте фабрика не вызывается: третьему объекту передали готовый given. Оба имени указывают на один список, поэтому append через given меняет и third.titles. У двух объектов с аргументом по умолчанию контейнеры независимы, а переданные явно элементы пока остаются общими. В практике исправим именно вторую ситуацию, проверив значение и сохранив отдельную копию внутри Task.`})]}),(0,b.jsxs)(s,{number:`03`,title:`Проверяем и принимаем владение явным списком`,children:[(0,b.jsx)(o,{children:`Конструктор получает либо новый список от фабрики, либо список, переданный вызывающим кодом. В обоих случаях поле Task должно владеть своим контейнером. Если мы сохраним входную ссылку как есть, вызывающий код сможет изменить уже созданную задачу снаружи.`}),(0,b.jsxs)(`p`,{children:[`Сначала убеждаемся, что значение является списком, затем проверяем элементы. Для каждого элемента проверяем тип, вызываем `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`strip()`}),` и отклоняем пустую строку. Возвращать нужно новый список с нормализованными строками, а не исходный контейнер. Такая чистая функция использует уже знакомый подход: проверка и подготовка значения идут до записи в состояние.`]}),(0,b.jsx)(`p`,{children:`Вторая аналогия здесь похожа на передачу списка гостей. Если мы оставим у себя общий лист, любая сторона сможет дописать имя и незаметно изменить данные другой. Мы делаем свою копию и записываем нормализованные имена в неё. Копируются именно ячейки списка; внутри они содержат строки, а строки неизменяемы. Для вложенных изменяемых объектов такой поверхностной копии было бы мало.`}),(0,b.jsx)(v,{code:`def validate_tags(tags):
    if not isinstance(tags, list):
        raise ValueError("Метки должны быть списком")

    normalized = []
    for tag in tags:
        if not isinstance(tag, str):
            raise ValueError("Каждая метка должна быть строкой")
        tag = tag.strip()
        if not tag:
            raise ValueError("Метка не может быть пустой")
        normalized.append(tag)
    return normalized`}),(0,b.jsx)(`p`,{children:`Порядок проверок здесь важен. Если сразу вызвать tag.strip() для списка [7], возникнет AttributeError, а по договору мы хотим понятный ValueError. Поэтому сначала проверяем, что tags: список, затем что каждый tag: строка, и только потом делаем strip(). Для ["   "] строка после очистки пуста: это тоже ValueError. Для [" x ", "x"] получаем два элемента "x" без удаления повтора.`}),(0,b.jsxs)(`p`,{children:[`Новая функция возвращает другой список даже тогда, когда все входные метки уже очищены. В dataclass результат этой функции присваивается полю в `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`__post_init__`}),`, который запускается после присваивания полей сгенерированным конструктором. Если проверка поднимает ValueError, обычное создание Task завершается отказом до того, как вызывающий код получит пригодный объект.`]}),(0,b.jsx)(n,{code:`@dataclass
class Task:
    tags: list[str] = field(default_factory=list)

    def __post_init__(self):
        if not isinstance(self.tags, list):
            raise ValueError("Ожидается список")`,question:`Что здесь упущено, даже если проверка типа проходит?`,options:[`Каждый экземпляр обязательно получает один общий список`,`Переданный список остаётся общей ссылкой, а элементы не проверяются и не очищаются`,`field должен быть импортирован из json`],correctIndex:1,explanation:`Проверка только формы списка не проверяет его элементы и не передаёт Task отдельный контейнер. Нужна функция, которая проверяет и нормализует каждый элемент, а затем возвращает новый список.`,fix:`self.tags = validate_tags(self.tags)`}),(0,b.jsxs)(`p`,{children:[`Мы не проверяем каждое будущее изменение автоматически. После создания обычный список всё ещё допускает`,(0,b.jsx)(`code`,{className:`lesson-token`,children:`task.tags.append(" ")`}),`. Такой вызов обходит конструктор и правила. В рамках текущего договора метки меняются через предусмотренный код модели; постоянная защита каждого append потребовала бы отдельного специального контейнера, который этот блок не вводит.`]})]}),(0,b.jsxs)(s,{number:`04`,title:`to_dict выдаёт собственный список записи`,children:[(0,b.jsxs)(o,{children:[`Метод `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`to_dict()`}),` задаёт формат передачи данных. После появления tags он перечисляет пять ключей: четыре старых поля и новый список. Важно скопировать контейнер при выдаче записи, иначе словарь и Task будут ссылаться на один список.`]}),(0,b.jsx)(`p`,{children:`Копия на границе похожа на отдельную распечатку списка меток. Получатель может делать пометки на своём листе, не меняя исходный документ модели. Это всё ещё список строк с теми же значениями, но сам контейнер имеет другую идентичность. Мы явно перечисляем поля, потому что они образуют формат записи; внутренний словарь атрибутов объекта не должен случайно стать контрактом данных.`}),(0,b.jsxs)(h,{caption:`Модель и словарь владеют разными списками`,children:[(0,b.jsxs)(p,{label:`Выдача новой записи`,children:[(0,b.jsx)(d,{title:`Task`,children:(0,b.jsx)(`p`,{children:`Собственный список tags`})}),(0,b.jsx)(f,{label:`to_dict копирует контейнер`}),(0,b.jsx)(d,{title:`Новая запись`,children:(0,b.jsx)(`p`,{children:`Пять полей и отдельный список`})})]}),(0,b.jsxs)(p,{label:`Восстановление объекта`,children:[(0,b.jsx)(d,{title:`Старая или новая запись`,children:(0,b.jsx)(`p`,{children:`Четыре обязательных поля, tags может отсутствовать`})}),(0,b.jsx)(f,{label:`конструктор проверяет и копирует`}),(0,b.jsx)(d,{title:`Новая Task`,children:(0,b.jsx)(`p`,{children:`Независимые значения модели`})})]})]}),(0,b.jsx)(`p`,{children:`Схему читаем слева направо в каждой строке. Верхний путь выдаёт копию списка в новую запись. Нижний принимает один из двух форматов и создаёт новый объект через конструктор; при старом формате он получит отдельный пустой список. Стрелки описывают преобразование значений, а не чтение или перезапись файла.`}),(0,b.jsx)(c,{question:`Какой вариант отделяет словарь от внутреннего списка Task?`,left:{title:`Передать ту же ссылку`,code:`"tags": self.tags`,note:`Оба контейнера можно менять через разные имена.`},right:{title:`Выдать отдельный список`,code:`"tags": list(self.tags)`,note:`Значения те же, контейнер принадлежит записи.`},preferred:`right`,explanation:`Копия изолирует контейнеры. Так изменение tags в возвращённом словаре не переписывает поле исходной Task.`}),(0,b.jsxs)(`p`,{children:[`Для нашего договора достаточно `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`list(self.tags)`}),`: элементы являются строками и не меняются на месте. Например, после `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`record = task.to_dict()`}),` можно выполнить `,(0,b.jsx)(`code`,{className:`lesson-token`,children:`record["tags"].append("новая")`}),`. Если Task не меняется, копия работает; если меняется, to_dict вернул чужой список. Проверка только равенства списков до append такой ошибки не обнаружит. Полученный словарь можно сериализовать позже, но сам конвертер не вызывает JSON, storage или файловые операции.`]})]}),(0,b.jsxs)(s,{number:`05`,title:`from_dict принимает оба предусмотренных формата`,children:[(0,b.jsx)(o,{children:`Старые записи содержат четыре обязательных ключа. Новая запись добавляет к ним tags. Поэтому отсутствие только этого нового поля можно понять как пустой список; остальные пропуски остаются ошибкой данных.`}),(0,b.jsx)(`p`,{children:`Сначала проверяем тип и набор ключей. Подходят ровно две формы: полный старый набор из четырёх полей или тот же набор вместе с tags. После проверки передаём поля в обычный конструктор. Там работают прежние правила id, title, priority и is_done, а новая проверка меток нормализует и копирует список.`}),(0,b.jsx)(v,{code:`record = {"id": 4, "title": "Читать", "priority": 2,
          "is_done": False, "tags": [" python "]}
old_part = dict(record)
old_part.pop("tags", None)
print(set(old_part))
print("tags" in record)`}),(0,b.jsx)(`p`,{children:`Если прежняя чистая проверка принимает ровно четыре поля, ей передают old_part после проверки новой записи. dict(record) создаёт новый внешний словарь, а pop удаляет ключ только из копии. Оригинал всё ещё содержит tags. Но список внутри пока общий: dict(record) его не копирует. Поэтому проверяем tags отдельно и передаём его конструктору Task: там validate_tags создаст собственный список. Модель не импортирует app.storage.`}),(0,b.jsx)(r,{tone:`warn`,children:`Отсутствующий tags в полной старой записи означает пустой список. Значение None, неверный тип или пропущенный старый ключ не означают пустое значение и не исправляются молча.`}),(0,b.jsx)(`p`,{children:`Так сохраняется совместимость чтения, а не универсальная терпимость к любой записи. Например, если у словаря нет is_done, мы не можем знать, была ли задача завершена. Подстановка False потеряла бы информацию и скрыла повреждение. Тот же подход сохраняет исходный id и приоритет, вместо повторного создания задачи через фабрику с новыми значениями.`}),(0,b.jsx)(m,{prompt:`Соединим вариант входной записи с ожидаемым поведением модели.`,leftTitle:`Вход`,rightTitle:`Результат`,pairs:[{left:`Полные четыре старых поля`,right:`Task с пустым отдельным tags`},{left:`Четыре старых поля и список tags`,right:`Task с проверенными метками`},{left:`Нет is_done или tags равен None`,right:`Явный отказ без подстановки`}],explanation:`Совместимость разрешена только для отсутствующего нового поля в полной старой записи. Остальные нарушения не маскируются.`}),(0,b.jsx)(`p`,{children:`При восстановлении исходный словарь остаётся нетронутым, а поле новой Task получает свой контейнер. Если позже изменить список в записи, модель не изменится. Если изменить tags модели после создания, ранее возвращённый словарь также сохранит свои значения. Так обе стороны границы можно менять независимо.`})]}),(0,b.jsxs)(s,{number:`06`,title:`Равенство и честные границы списка`,children:[(0,b.jsx)(o,{children:`Dataclass сравнивает значения полей, поэтому список tags участвует в равенстве двух Task. Если метки совпадают по значениям и порядку, а остальные поля тоже равны, выражение с оператором == вернёт True. Оператор is проверяет другой вопрос: ссылаются ли имена на один и тот же объект.`}),(0,b.jsx)(l,{code:`a = ["python"]
b = list(a)
print(a == b)
print(a is b)
b.append("review")
print(a == b)
print(a)`,output:`True
False
False
['python']`,hint:`Сначала сравним значения и объекты, затем изменим только копию b.`}),(0,b.jsx)(`p`,{children:`Сначала == возвращает True, потому что в обоих списках одна и та же строка; is возвращает False, потому что контейнеры разные. После append только b содержит "review", поэтому == становится False, а a остаётся прежним. С моделью та же логика: при круге Task → словарь → Task мы сравниваем все поля, но получаем новую Task и новый список tags.`}),(0,b.jsx)(`p`,{children:`После преобразования Task в словарь и обратно мы ожидаем равные поля, но получаем новый объект. Это нормальный результат round trip. Для dataclass сравнение == охватывает все пять полей, включая порядок tags. Если восстановленный список дополнить меткой, две Task перестанут быть равны по значениям, хотя каждая останется отдельным объектом. А если восстановить один и тот же словарь дважды, равенство может быть True при разных id объектов в памяти. Для проверки независимости нужны и ==, и is, и изменение только одного из списков.`}),(0,b.jsx)(r,{tone:`warn`,children:`Проверка конструктора действует при создании: вызов task.tags.append(" ") позже её обходит. Обычный список не проверяет последующие изменения, а dataclass не делает атрибуты защищёнными. Наша гарантия точнее: отдельный default, проверенный вход и копии на обеих границах конвертеров.`}),(0,b.jsx)(`p`,{children:`Наконец, эти пять полей пока принадлежат только подготовленной Task. Старый storage проверяет ровно четыре ключа, поэтому новую запись с tags нельзя передавать туда для сохранения. CLI и рабочий JSON не меняются в этом занятии. После завершённой миграции следующий этап согласованно обновит потребителей и схему, а до него мы проверяем новый формат на объектах в памяти или на отдельной учебной копии.`})]}),(0,b.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:"Теперь соберём доказательства для каждого владельца списка и для обеих форм словаря. Мы будем изменять ту же модель в `app.models`, опираясь на dataclass, проверяемый конструктор и конвертеры предыдущего шага."}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Добавим поле`,description:`Отдельный default и проверка явных меток дадут Task нормализованный собственный список.`},{title:`Проверим границы`,description:`Конвертеры сохранят значения, а выдаваемый или восстановленный контейнер не будет общим.`},{title:`Подтвердим совместимость`,description:`Полная старая запись восстановится, ошибка обязательного поля останется видимой.`},{title:`Пройдём регрессию`,description:`Словарный CLI и четырёхпольный storage продолжат работать без записи нового формата.`}]}),(0,b.jsx)(`p`,{children:`Начнём с фактического состояния собственного проекта: здесь нужна одна Task после dataclass и готовые четыре поля. Затем добавим tags к той же модели, проверим отказ некорректного значения, независимость контейнеров и сохранение порядка. Конвертеры пройдут круг между Task и словарём, не открывая файл и не меняя рабочий storage.`}),(0,b.jsx)(`p`,{children:`Результат подтвердим сравнением значений и идентичности объектов, изменением копий на обеих границах, а также отдельным запуском прежнего CLI на четырёхпольных данных. Далее выберем форму компонентов и разберём их сотрудничество на отдельном примере. Подключение Task к операциям и запись tags в рабочий JSON относятся уже к подключению Task к операциям и хранению в блоке 8.`})]})]})}export{x as Lesson34_1};